// Verification host only. Replacement, String storage, workers and collection execute MASM.
using System;
using System.Collections.Generic;
using System.Runtime.InteropServices;
using System.Text;
public static class BoomReplaceProbe {
    [StructLayout(LayoutKind.Sequential)] struct Context {public uint Kind,PC,Method,Depth;}
    [DllImport("kernel32.dll",CharSet=CharSet.Unicode)] static extern IntPtr LoadLibraryExW(string p,IntPtr z,uint f);
    [DllImport("kernel32.dll",CharSet=CharSet.Ansi)] static extern IntPtr GetProcAddress(IntPtr m,string n);
    [DllImport("kernel32.dll")] static extern bool FreeLibrary(IntPtr m);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Create(ulong n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int Bind(IntPtr h);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate int Destroy(IntPtr h);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Get();
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Roots(out uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate ulong Collect(IntPtr h,IntPtr roots,uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Alloc(IntPtr h,ulong bytes,uint refs,uint type);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate ulong Entry(ref Context c,[In] ulong[] args);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr Service(ref Context c,[In] ulong[] args,IntPtr pool);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate IntPtr PoolCreate(uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate uint PoolRun(IntPtr p,IntPtr fn,IntPtr input,IntPtr output,uint n);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate uint PoolDestroy(IntPtr p);
    [UnmanagedFunctionPointer(CallingConvention.Cdecl)] delegate uint Release();
    static void Check(bool ok,string s){if(!ok)throw new Exception(s);}
    static IntPtr Open(string p){IntPtr m=LoadLibraryExW(p,IntPtr.Zero,0x1100);Check(m!=IntPtr.Zero,"Replace module load failed");return m;}
    static T Fn<T>(IntPtr m,string n){IntPtr p=GetProcAddress(m,n);Check(p!=IntPtr.Zero,"Missing "+n);return Marshal.GetDelegateForFunctionPointer<T>(p);}
    static void Close(IntPtr m,IntPtr h){IntPtr p=GetProcAddress(m,"boom_release_trace_pool");if(p!=IntPtr.Zero)Check(Marshal.GetDelegateForFunctionPointer<Release>(p)()==0,"Replace frames still active");if(h!=IntPtr.Zero)Check(Fn<Destroy>(m,"boom_heap_destroy")(h)!=0,"Replace heap cleanup failed");FreeLibrary(m);}
    static string Text(IntPtr p){Check(p!=IntPtr.Zero&&Marshal.ReadInt64(p,-16)==16&&Marshal.ReadInt32(p,-20)==1,"Malformed replacement String");IntPtr chars=Marshal.ReadIntPtr(p);long bytes=Marshal.ReadInt64(chars,-16);Check(bytes>=0&&(bytes&1)==0&&bytes<=131070&&Marshal.ReadInt64(chars,-8)==261,"Malformed replacement char[]");return Marshal.PtrToStringUni(chars,checked((int)bytes/2));}
    static int Reachable(IntPtr roots,uint n){var live=new HashSet<IntPtr>();var todo=new Stack<IntPtr>();for(int i=0;i<n;i++)todo.Push(Marshal.ReadIntPtr(roots,i*8));while(todo.Count!=0){IntPtr p=todo.Pop();if(p==IntPtr.Zero||!live.Add(p))continue;uint f=unchecked((uint)Marshal.ReadInt32(p,-24)),refs=unchecked((uint)Marshal.ReadInt32(p,-20));long bytes=Marshal.ReadInt64(p,-16);Check((f&0xfffffffd)==0xb00b0001&&bytes>=0&&refs<=(ulong)bytes/8&&live.Count<1048576,"Malformed replacement graph");for(int i=0;i<refs;i++)todo.Push(Marshal.ReadIntPtr(p,i*8));}return live.Count;}
    static void GC(IntPtr m,IntPtr h,params IntPtr[] extra){IntPtr roots=Fn<Roots>(m,"boom_get_static_roots")(out uint n),all=Marshal.AllocHGlobal(checked(((int)n+extra.Length)*8));try{for(int i=0;i<n;i++)Marshal.WriteIntPtr(all,i*8,Marshal.ReadIntPtr(roots,i*8));for(int i=0;i<extra.Length;i++)Marshal.WriteIntPtr(all,((int)n+i)*8,extra[i]);uint count=checked(n+(uint)extra.Length);int live=Reachable(all,count);Check(Fn<Collect>(m,"boom_heap_collect")(h,all,count)!=ulong.MaxValue&&Marshal.ReadInt64(h,56)==live,"Replacement roots lost or temporary graph leaked");}finally{Marshal.FreeHGlobal(all);}}
    static IntPtr Invoke(Entry e,params ulong[] args){var c=new Context();ulong v=e(ref c,args);Check(v!=0&&c.Kind==0&&c.Depth==0,"Replacement object entry failed: "+c.Kind);return new IntPtr(unchecked((long)v));}
    static IntPtr Replace(Service f,IntPtr pool,IntPtr s,uint old,uint neo){var c=new Context();IntPtr r=f(ref c,new ulong[]{unchecked((ulong)s.ToInt64()),old,neo},pool);Check(r!=IntPtr.Zero&&c.Kind==0,"Native replacement failed: "+c.Kind);return r;}
    public static string[] Raw(string dll,string[] cases){IntPtr m=Open(dll),h=IntPtr.Zero;try{h=Fn<Create>(m,"boom_heap_create")(4*1024*1024);Check(h!=IntPtr.Zero&&Fn<Bind>(m,"boom_bind_heap")(h)==1,"Raw replacement heap failed");var e=Fn<Entry>(m,"boom_entry");var output=new string[cases.Length];for(int i=0;i<cases.Length;i++){string[] a=cases[i].Split(' ');IntPtr r=Invoke(e,Convert.ToUInt32(a[0],16),Convert.ToUInt32(a[1],16));var hex=new StringBuilder();foreach(char c in Text(r))hex.Append(((int)c).ToString("x4"));output[i]=hex.ToString();GC(m,h);}return output;}finally{Close(m,h);}}
    public static void Objects(string dll,string runtime){IntPtr m=Open(dll),r=Open(runtime),h=IntPtr.Zero;try{h=Fn<Create>(m,"boom_heap_create")(65536);Check(h!=IntPtr.Zero&&Fn<Bind>(m,"boom_bind_heap")(h)==1,"Object replacement heap failed");var e=Fn<Entry>(m,"boom_entry");var f=Fn<Service>(m,"boom_string_replace");IntPtr pool=Fn<Get>(m,"boom_get_replace_string_pool")();var source=new IntPtr[8];for(uint i=0;i<8;i++)source[i]=Invoke(e,i);GC(m,h);long baseline=Marshal.ReadInt64(h,56);IntPtr a=Replace(f,pool,source[1],97,98),b=Replace(f,pool,source[1],97,98);Check(Text(a)=="bbbbb"&&Text(b)=="bbbbb"&&Text(source[1])=="ababa"&&a!=b&&a!=source[1]&&Marshal.ReadIntPtr(a)!=Marshal.ReadIntPtr(b)&&Marshal.ReadIntPtr(a)!=Marshal.ReadIntPtr(source[1])&&Marshal.ReadInt64(h,56)==baseline+4,"Changed replacement did not copy immutable storage");GC(m,h,a,b);Check(Text(a)=="bbbbb"&&Text(b)=="bbbbb","Replacement copy roots lost");GC(m,h);
        for(int i=0;i<128;i++){long before=Marshal.ReadInt64(h,56);Check(Replace(f,pool,source[1],97,97)==source[1]&&Replace(f,pool,source[1],113,120)==source[1]&&Replace(f,pool,source[0],0,1)==source[0]&&Marshal.ReadInt64(h,56)==before,"Unchanged replacement allocated or lost identity");IntPtr changed=Replace(f,pool,source[1],97,98);Check(Text(changed)=="bbbbb"&&Marshal.ReadInt64(h,56)==before+2,"Changed replacement allocation budget exceeded");GC(m,h);}
        var c=new Context{Kind=9,PC=17,Method=23,Depth=3};Check(f(ref c,new ulong[]{0,0,0},IntPtr.Zero)==IntPtr.Zero&&c.Kind==9&&c.PC==17&&c.Method==23&&c.Depth==3,"Replacement changed pending exception");c=new Context{PC=17,Method=23};Check(f(ref c,new ulong[]{0,97,97},pool)==IntPtr.Zero&&c.Kind==4&&c.PC==17&&c.Method==23,"Replacement null check/identity order incorrect");
        IntPtr copy=Marshal.AllocHGlobal(80);try{byte[] data=new byte[80];Marshal.Copy(pool,data,0,80);foreach(int off in new[]{0,4,16,40,48,64}){Marshal.Copy(data,0,copy,80);if(off<24)Marshal.WriteInt32(copy,off,off==16?65537:7);else Marshal.WriteIntPtr(copy,off,IntPtr.Zero);c=new Context();Check(f(ref c,new ulong[]{unchecked((ulong)source[1].ToInt64()),97,98},copy)==IntPtr.Zero&&c.Kind==7,"Replacement accepted malformed pool: "+off);}
            IntPtr foreign=Fn<Create>(m,"boom_heap_create")(65536);Check(foreign!=IntPtr.Zero,"Replacement foreign heap failed");try{Marshal.Copy(data,0,copy,80);Marshal.WriteIntPtr(copy,48,foreign);c=new Context();Check(f(ref c,new ulong[]{unchecked((ulong)source[1].ToInt64()),97,98},copy)==IntPtr.Zero&&c.Kind==7,"Replacement accepted foreign heap");}finally{Check(Fn<Destroy>(m,"boom_heap_destroy")(foreign)!=0,"Replacement foreign heap cleanup failed");}
        }finally{Marshal.FreeHGlobal(copy);}Check(Marshal.ReadInt64(h,56)==baseline,"Replacement metadata gates allocated");
        var alloc=Fn<Alloc>(r,"boom_heap_alloc");IntPtr hole=alloc(h,16,0,267);Check(hole!=IntPtr.Zero,"Replacement partial OOM hole failed");var fillers=new List<IntPtr>();IntPtr block;while((block=alloc(h,4096,0,267))!=IntPtr.Zero)fillers.Add(block);while((block=alloc(h,0,0,267))!=IntPtr.Zero)fillers.Add(block);GC(m,h,fillers.ToArray());long count=Marshal.ReadInt64(h,56);c=new Context{PC=17,Method=23};Check(f(ref c,new ulong[]{unchecked((ulong)source[1].ToInt64()),97,98},pool)==IntPtr.Zero&&c.Kind==3&&c.PC==17&&c.Method==23&&Marshal.ReadInt64(h,56)==count+1,"Second replacement allocation failure not exercised");GC(m,h,fillers.ToArray());Check(Marshal.ReadInt64(h,56)==count,"Partial replacement array retained");GC(m,h);Check(Text(Replace(f,pool,source[1],97,98))=="bbbbb","Replacement OOM recovery failed");GC(m,h);
    }finally{Close(m,h);FreeLibrary(r);}}
    public static void Tail(string dll,string runtime){IntPtr m=Open(dll),r=Open(runtime),h=IntPtr.Zero;try{h=Fn<Create>(m,"boom_heap_create")(65536);Check(h!=IntPtr.Zero&&Fn<Bind>(m,"boom_bind_heap")(h)==1,"Tail replacement heap failed");IntPtr s=Invoke(Fn<Entry>(m,"boom_entry"),0),pool=Fn<Get>(m,"boom_get_replace_string_pool")();var alloc=Fn<Alloc>(r,"boom_heap_alloc");long left=Marshal.ReadInt64(h,16)-Marshal.ReadInt64(h,48);if((left&31)!=0)Check(alloc(h,16,0,267)!=IntPtr.Zero,"Tail alignment setup failed");IntPtr last=IntPtr.Zero,v;while((v=alloc(h,0,0,261))!=IntPtr.Zero)last=v;Check(last!=IntPtr.Zero&&last==Marshal.ReadIntPtr(h,24),"Empty backing array did not reach exact heap boundary");Marshal.WriteIntPtr(s,last);long before=Marshal.ReadInt64(h,56);Check(Replace(Fn<Service>(m,"boom_string_replace"),pool,s,0,1)==s&&Marshal.ReadInt64(h,56)==before,"Valid empty tail array rejected by replacement");GC(m,h);Check(Text(s)==""&&Marshal.ReadIntPtr(s)==last,"Empty tail backing array not retained by GC");long count=Marshal.ReadInt64(h,56);var ctx=new Context();IntPtr result=Fn<Service>(r,"boom_string_concat_api")(ref ctx,new ulong[]{unchecked((ulong)s.ToInt64()),unchecked((ulong)s.ToInt64())},pool);Check(result==s&&ctx.Kind==0&&Marshal.ReadInt64(h,56)==count,"Concat rejected valid empty tail array or allocated: "+ctx.Kind);}finally{Close(m,h);FreeLibrary(r);}}
    public static void FullHeap(string dll,string runtime){IntPtr m=Open(dll),r=Open(runtime),h=IntPtr.Zero;try{h=Fn<Create>(m,"boom_heap_create")(65536);Check(h!=IntPtr.Zero&&Fn<Bind>(m,"boom_bind_heap")(h)==1,"Full replacement heap failed");var e=Fn<Entry>(m,"boom_entry");for(uint i=0;i<4;i++){var c=new Context();e(ref c,new ulong[]{i});Check(c.Kind==0,"Replacement OOM warmup failed");}GC(m,h);var alloc=Fn<Alloc>(r,"boom_heap_alloc");while(alloc(h,4096,0,267)!=IntPtr.Zero){}while(alloc(h,0,0,267)!=IntPtr.Zero){}long full=Marshal.ReadInt64(h,56);for(uint i=0;i<256;i++){var c=new Context();uint n=i&3;ulong v=e(ref c,new ulong[]{n});Check(v==(n<2?21UL:97UL)&&c.Kind==0&&c.Depth==0&&Marshal.ReadInt64(h,56)==full,"Full-heap source identity or OOM catch mismatch");}GC(m,h);}finally{Close(m,h);FreeLibrary(r);}}
    public static void Parallel(string dll,string runtime,int[] expected){const uint n=2049;IntPtr m=Open(dll),r=Open(runtime),h=IntPtr.Zero,p=IntPtr.Zero,input=IntPtr.Zero,output=IntPtr.Zero;try{h=Fn<Create>(m,"boom_heap_create")(32*1024*1024);Check(h!=IntPtr.Zero&&Fn<Bind>(m,"boom_bind_heap")(h)==1&&expected.Length==n,"Replacement worker setup failed");p=Fn<PoolCreate>(r,"boom_pool_create")(8);Check(p!=IntPtr.Zero,"Replacement worker pool failed");input=Marshal.AllocHGlobal((int)n*128);output=Marshal.AllocHGlobal((int)n*32);for(int i=0;i<n;i++)Marshal.WriteInt64(input,i*128,i);for(int batch=0;batch<3;batch++){Check(Fn<PoolRun>(r,"boom_pool_run")(p,GetProcAddress(m,"boom_entry"),input,output,n)==0,"Replacement worker batch failed");for(int i=0;i<n;i++)Check(unchecked((int)Marshal.ReadInt64(output,i*32))==expected[i]&&Marshal.ReadInt64(output,i*32+8)==0&&Marshal.ReadInt64(output,i*32+16)==0&&Marshal.ReadInt64(output,i*32+24)==0,"Replacement result/context crossed workers");GC(m,h);}}finally{if(p!=IntPtr.Zero)Check(Fn<PoolDestroy>(r,"boom_pool_destroy")(p)==0,"Replacement workers active at cleanup");if(input!=IntPtr.Zero)Marshal.FreeHGlobal(input);if(output!=IntPtr.Zero)Marshal.FreeHGlobal(output);Close(m,h);FreeLibrary(r);}}
}
